set -euo pipefail

# Question 1: One worker takes no Pods
case "${Q1_FAULT}" in
  cordoned)
    kubectl uncordon "${Q1_NODE}"
    ;;
  taint-noschedule)
    kubectl taint node "${Q1_NODE}" dedicated-
    ;;
  taint-noexecute)
    kubectl taint node "${Q1_NODE}" maintenance-
    ;;
  label-removed)
    kubectl label node "${Q1_NODE}" tier=app --overwrite
    ;;
  max-pods) ;;
esac

case "${Q1_FAULT}" in
  cordoned)
    kubectl -n "spread" rollout status deployment/spread --timeout=240s
    ;;
  taint-noschedule)
    kubectl -n "spread" rollout status deployment/spread --timeout=240s
    ;;
  taint-noexecute)
    kubectl -n "spread" rollout status deployment/spread --timeout=240s
    ;;
  label-removed)
    kubectl -n "spread" rollout status deployment/spread --timeout=240s
    ;;
  max-pods)
    for _ in $(seq 1 90); do
      [[ "$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')" == True ]] && break
      sleep 2
    done
    kubectl -n "spread" rollout status deployment/spread --timeout=240s
    ;;
esac
